// Daily Word for the Atlas95 Game Vault: guess the 5-letter word in 6 tries.
(()=>{
// answer words, then every other accepted guess, packed 5 letters at a time
const ANS="";
const GUESS="";
const split=s=>s.match(/.{5}/g);
const ANSWERS=split(ANS),VALID=new Set([...ANSWERS,...split(GUESS)]);
// The daily order is a fixed shuffle of ANSWERS, so adding or removing answers reshuffles every future day.
const EPOCH="2026-01-01";
const ROWS=[..."qwertyuiop"],ROW2=[..."asdfghjkl"],ROW3=[..."zxcvbnm"];
const CSS=`
.dw-wrap{display:flex;flex-direction:column;align-items:center;gap:10px}
.dw-msg{min-height:1.5em;font-weight:700;text-align:center}
.dw-board{display:grid;grid-template-rows:repeat(6,1fr);gap:5px;background:var(--hi);box-shadow:var(--sunken);padding:10px;width:min(100%,clamp(210px,calc(100vh - 430px),300px))}
.dw-row{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}
.dw-row.shake{animation:dwshake .4s}
.dw-t{aspect-ratio:1;display:flex;align-items:center;justify-content:center;font:700 clamp(18px,6vw,26px) var(--ui);text-transform:uppercase;background:var(--hi);box-shadow:inset 0 0 0 2px #c0c0c0}
.dw-t.on{box-shadow:inset 0 0 0 2px #404040;animation:dwpop .12s}
.dw-t.g,.dw-t.y,.dw-t.b{color:#fff;box-shadow:none}
.dw-t.g{background:#6aaa64}.dw-t.y{background:#c9b458}.dw-t.b{background:#787c7e}
.dw-t.rev{animation:dwflip .5s both;animation-delay:calc(var(--i)*.25s)}
.dw-kb{display:flex;flex-direction:column;gap:5px;width:min(100%,500px)}
.dw-kr{display:flex;gap:4px;justify-content:center}
.dw-kb .btn{flex:1 1 0;min-width:0;padding:0;min-height:min(46px,6.5vh);font-weight:700;text-transform:uppercase;font-size:14px}
.dw-kb .btn.wide{flex:1.6 1 0;font-size:12px;text-transform:none}
.dw-kb .btn.g{background:#6aaa64;color:#fff}.dw-kb .btn.y{background:#c9b458;color:#fff}.dw-kb .btn.b{background:#787c7e;color:#fff}
.dw-end{display:flex;flex-direction:column;gap:8px;width:min(100%,420px)}
.dw-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;text-align:center}
.dw-stats b{display:block;font-size:22px}
.dw-stats span{font-size:11.5px}
.dw-dist{display:grid;grid-template-columns:auto 1fr;gap:3px 6px;align-items:center;font-size:12px}
.dw-dist i{display:block;background:#787c7e;color:#fff;font-style:normal;font-weight:700;text-align:right;padding:1px 5px;min-width:18px}
.dw-dist i.me{background:#6aaa64}
@keyframes dwflip{0%{transform:rotateX(0);background:var(--hi);color:var(--ink);box-shadow:inset 0 0 0 2px #404040}49%{transform:rotateX(90deg);background:var(--hi);color:var(--ink);box-shadow:inset 0 0 0 2px #404040}50%{transform:rotateX(90deg)}100%{transform:rotateX(0)}}
@keyframes dwpop{50%{transform:scale(1.08)}}
@keyframes dwshake{20%,60%{transform:translateX(-6px)}40%,80%{transform:translateX(6px)}}
@media (prefers-reduced-motion:reduce){.dw-t.rev,.dw-t.on,.dw-row.shake{animation:none}}`;
function rate(guess,ans){const res=Array(5).fill("b"),left={};
  for(let i=0;i<5;i++){if(guess[i]===ans[i])res[i]="g";else left[ans[i]]=(left[ans[i]]||0)+1}
  for(let i=0;i<5;i++)if(res[i]!=="g"&&left[guess[i]]){res[i]="y";left[guess[i]]--}return res}
A95G.word={
help:`<div>Guess the hidden 5-letter word in 6 tries. After each guess, the tiles change color:</div>
<ul class="factlist"><li><b style="color:#4a8a44">Green:</b> right letter, right spot.</li><li><b style="color:#a08c30">Yellow:</b> the letter is in the word, but somewhere else.</li><li><b style="color:#606060">Gray:</b> the letter isn't in the word.</li></ul>
<div>Everyone gets the same word each day, and a new one comes at midnight. Want more? Try <b>Practice</b> for unlimited random words (they don't count toward your streak).</div>`,
mount(api){
  api.css(CSS);const st=api.stats;st.days=st.days||{};st.dist=st.dist||{};
  const today=api.today(),dayIdx=api.dayNum(today)-api.dayNum(EPOCH),order=api.shuffle(ANSWERS,api.rng("a95-daily-word"));
  const daily=order[((dayIdx%order.length)+order.length)%order.length];
  let mode="daily",ans,guesses,cur,done,busy=false;
  function load(m){mode=m;cur="";busy=false;
    if(m==="daily"){ans=daily;const d=st.days[today];if(d){guesses=d.g.slice();done=true}else{guesses=st.cur&&st.cur.d===today?st.cur.g.slice():[];done=false}}
    else{const rnd=api.begin({});do{ans=ANSWERS[Math.floor(rnd()*ANSWERS.length)]}while(ans===daily);guesses=[];done=false}
    api.bar.innerHTML=`<button class="btn" type="button" data-dw="daily" aria-pressed="${m==="daily"}">Today's word</button><button class="btn" type="button" data-dw="practice" aria-pressed="${m==="practice"}">${m==="practice"?"New practice word":"Practice"}</button>`;
    render();say(m==="daily"?(done?"":`Daily Word for ${api.niceDate(today)}`):"Practice word: guess away!")}
  function say(t){const e=api.root.querySelector(".dw-msg");if(e)e.textContent=t}
  function keyState(){const k={};guesses.forEach(g=>rate(g,ans).forEach((r,i)=>{const L=g[i],o=k[L];if(r==="g"||(r==="y"&&o!=="g")||(!o))k[L]=r}));return k}
  function rowHTML(i,reveal){const g=guesses[i];
    if(g){const r=rate(g,ans);return `<div class="dw-row">${[...g].map((c,j)=>`<span class="dw-t ${r[j]}${reveal?" rev":""}" style="--i:${j}">${c}</span>`).join("")}</div>`}
    if(i===guesses.length&&!done)return `<div class="dw-row" id="dwcur">${[0,1,2,3,4].map(j=>`<span class="dw-t${cur[j]?" on":""}">${cur[j]||""}</span>`).join("")}</div>`;
    return `<div class="dw-row">${"<span class=\"dw-t\"></span>".repeat(5)}</div>`}
  function render(reveal){const ks=keyState();
    api.root.innerHTML=`<div class="dw-wrap"><div class="dw-msg" aria-live="polite"></div><div class="dw-board" role="grid" aria-label="Guesses">${[0,1,2,3,4,5].map(i=>rowHTML(i,reveal&&i===guesses.length-1)).join("")}</div>
      ${done?endHTML():`<div class="dw-kb">${[ROWS,ROW2,ROW3].map((row,ri)=>`<div class="dw-kr">${ri===2?`<button class="btn wide" type="button" data-k="enter">Enter</button>`:""}${row.map(c=>`<button class="btn ${ks[c]||""}" type="button" data-k="${c}">${c}</button>`).join("")}${ri===2?`<button class="btn wide" type="button" data-k="back" aria-label="Backspace">⌫</button>`:""}</div>`).join("")}</div>`}</div>`;
    status()}
  function drawCur(){const row=api.root.querySelector("#dwcur");if(!row)return;row.innerHTML=[0,1,2,3,4].map(j=>`<span class="dw-t${cur[j]?" on":""}">${cur[j]||""}</span>`).join("")}
  function endHTML(){const won=guesses[guesses.length-1]===ans,n=guesses.length,daily_=mode==="daily";
    const w=st.wins||0,p=Object.keys(st.days).length,mx=Math.max(1,...[1,2,3,4,5,6].map(i=>st.dist[i]||0));
    const now=new Date(),mid=new Date(now.getFullYear(),now.getMonth(),now.getDate()+1),left=mid-now;
    return `<div class="dw-end"><div class="fb ${won?"ok":"no"}" style="text-align:center">${won?(["Genius!","Magnificent!","Impressive!","Splendid!","Great!","Phew!"][n-1]):`The word was <b>${ans.toUpperCase()}</b>.`}</div>
      ${daily_?`<div class="dw-stats"><div><b>${p}</b><span>Played</span></div><div><b>${p?Math.round(w/p*100):0}</b><span>Win %</span></div><div><b>${st.streak||0}</b><span>Streak</span></div><div><b>${st.maxStreak||0}</b><span>Max streak</span></div></div>
      <div class="dw-dist">${[1,2,3,4,5,6].map(i=>`<span>${i}</span><i class="${won&&i===n?"me":""}" style="width:${Math.max(8,Math.round((st.dist[i]||0)/mx*100))}%">${st.dist[i]||0}</i>`).join("")}</div>
      <div class="note" style="text-align:center">Next word in ${Math.floor(left/36e5)}h ${Math.floor(left%36e5/6e4)}m</div>`:""}
      <div class="actions" style="justify-content:center">${daily_?`<button class="btn default" type="button" data-dwshare>Share...</button>`:""}<button class="btn${daily_?"":" default"}" type="button" data-dw="practice">${daily_?"Practice word":"Another word"}</button></div></div>`}
  function status(){api.status(mode==="daily"?`Daily Word · ${api.niceDate(today)}`:"Practice",`Streak: ${st.streak||0}`)}
  function type(k){if(done||busy)return;
    if(k==="back"){cur=cur.slice(0,-1);drawCur();return}
    if(k==="enter"){submit();return}
    if(/^[a-z]$/.test(k)&&cur.length<5){cur+=k;drawCur()}}
  function bad(t){say(t);const row=api.root.querySelector("#dwcur");if(row){row.classList.remove("shake");void row.offsetWidth;row.classList.add("shake")}}
  function submit(){if(cur.length<5){bad("Not enough letters");return}if(!VALID.has(cur)){bad("Not in the word list");return}
    guesses.push(cur);cur="";const won=guesses[guesses.length-1]===ans,lost=!won&&guesses.length>=6;
    if(mode==="daily"&&!won&&!lost){st.cur={d:today,g:guesses.slice()};api.save()}
    if(won||lost)done=true;
    busy=true;render(true);const wait=api.reduced()?0:1400;
    setTimeout(()=>{busy=false;if(done)finish(won);else{api.sound("tap");say("")}},wait)}
  function finish(won){const n=guesses.length;
    if(mode==="daily"&&!st.days[today]){st.days[today]={g:guesses.slice(),won,n};st.cur=null;
      const yd=(()=>{const d=new Date(today+"T12:00:00");d.setDate(d.getDate()-1);return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")})();
      if(won){st.wins=(st.wins||0)+1;st.dist[n]=(st.dist[n]||0)+1;st.streak=st.days[yd]&&st.days[yd].won?(st.streak||0)+1:1;st.maxStreak=Math.max(st.maxStreak||0,st.streak);st.min=Math.min(st.min||9,n)}
      else st.streak=0;
      const r=api.result({xp:won?34-n*4:5});render();say(won?`Solved in ${n}!${r.xp?` +${r.xp} XP`:""}`:"So close. Try again tomorrow!")}
    else{const r=api.result({xp:won?4:1,ch:{v:won?n:7,text:won?`${n}/6`:"X/6",higher:false}});render();say(won?`Solved in ${n}!${r.xp?` +${r.xp} XP`:""}`:"")}
    api.sound(won?"win":"lose");const b=api.root.querySelector(".dw-end .btn.default");if(b&&matchMedia("(pointer:fine)").matches)b.focus({preventScroll:true})}
  function share(btn){const d=st.days[today];if(!d)return;const E={g:"🟩",y:"🟨",b:"⬜"};
    api.share(`Atlas95 Daily Word · ${api.niceDate(today)} ${d.won?d.n:"X"}/6\n${d.g.map(g=>rate(g,daily).map(r=>E[r]).join("")).join("\n")}${st.streak>1?`\n🔥 ${st.streak}-day streak`:""}`,btn)}
  api.on(api.root,"click",e=>{const k=e.target.closest("[data-k]");if(k){type(k.dataset.k);return}
    const s=e.target.closest("[data-dwshare]");if(s){share(s);return}const m=e.target.closest("[data-dw]");if(m)load(m.dataset.dw)});
  api.on(api.bar,"click",e=>{const m=e.target.closest("[data-dw]");if(m)load(m.dataset.dw)});
  api.on(document,"keydown",e=>{if(!api.active()||e.ctrlKey||e.metaKey||e.altKey||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;
    if(e.key==="Enter"){if(e.target.closest&&e.target.closest("button")&&!e.target.closest(".dw-kb"))return;e.preventDefault();type("enter")}
    else if(e.key==="Backspace"){e.preventDefault();type("back")}else if(/^[a-zA-Z]$/.test(e.key))type(e.key.toLowerCase())});
  load(api.seeded()?"practice":"daily");
  return {unmount(){}};
}};
})();
